-- NEXUS Commerce OS core schema. Apply only to a dedicated NEXUS Supabase project; never reuse gten-core.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table if not exists public.workspaces (id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 2 and 100), slug text not null unique, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.workspace_members (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'member' check(role in ('owner','admin','member','analyst')), created_at timestamptz not null default now(), unique(workspace_id,user_id));
create or replace function private.is_workspace_member(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=auth.uid()); $$;
create or replace function private.can_manage_workspace(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=auth.uid() and wm.role in ('owner','admin')); $$;
create or replace function public.create_workspace(p_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_id uuid:=gen_random_uuid(); v_slug text; begin if v_user is null then raise exception 'authentication required' using errcode='28000'; end if; if p_name is null or char_length(trim(p_name)) not between 2 and 100 then raise exception 'invalid workspace name' using errcode='22023'; end if; v_slug:=coalesce(nullif(trim(both '-' from regexp_replace(lower(trim(p_name)),'[^a-z0-9]+','-','g')),''),'workspace'); v_slug:=left(v_slug,80)||'-'||left(replace(v_id::text,'-',''),8); insert into public.workspaces(id,name,slug,created_by) values(v_id,trim(p_name),v_slug,v_user); insert into public.workspace_members(workspace_id,user_id,role) values(v_id,v_user,'owner'); return v_id; end; $$;
revoke all on function private.is_workspace_member(uuid) from public;
revoke all on function private.can_manage_workspace(uuid) from public;
revoke all on function public.create_workspace(text) from public;
grant execute on function private.is_workspace_member(uuid) to authenticated;
grant execute on function private.can_manage_workspace(uuid) to authenticated;
grant execute on function public.create_workspace(text) to authenticated;
create table if not exists public.products (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, created_by uuid not null references auth.users(id), sku text, title text not null check(char_length(title) between 2 and 240), brand text, category text, description text, materials text[] not null default '{}', colors text[] not null default '{}', sizes text[] not null default '{}', base_price numeric(14,2) check(base_price is null or base_price>=0), currency char(3) not null default 'USD', source_channel text not null default 'manual', source_product_id text, source_url text, attributes jsonb not null default '{}'::jsonb, status text not null default 'draft' check(status in ('draft','ready','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists products_workspace_sku_unique on public.products(workspace_id,sku) where sku is not null and sku<>'';
create index if not exists products_workspace_updated_idx on public.products(workspace_id,updated_at desc);
create table if not exists public.agent_runs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, actor_user_id uuid not null references auth.users(id), product_id uuid references public.products(id) on delete set null, task_type text not null, status text not null default 'queued' check(status in ('queued','running','succeeded','failed')), provider text, model text, input jsonb not null default '{}'::jsonb, output jsonb, error_code text, input_tokens integer, output_tokens integer, created_at timestamptz not null default now(), completed_at timestamptz);
create index if not exists agent_runs_workspace_created_idx on public.agent_runs(workspace_id,created_at desc);
create table if not exists public.channel_listings (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_by uuid not null references auth.users(id), channel text not null check(channel in ('shopify','amazon','tiktok_shop','shoplazza','woocommerce','other')), market text not null, locale text not null default 'en-US', version integer not null default 1 check(version>0), content jsonb not null, status text not null default 'draft' check(status in ('draft','review','approved','published','rejected')), external_listing_id text, approved_at timestamptz, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(product_id,channel,market,locale,version));
create table if not exists public.product_assets (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, created_by uuid not null references auth.users(id), object_path text not null, asset_type text not null check(asset_type in ('product_photo','lifestyle','video','document','generated','other')), mime_type text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(workspace_id,object_path));
create table if not exists public.channel_connections (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, provider text not null check(provider in ('shopify','amazon','tiktok_shop','shoplazza','woocommerce','other')), display_name text not null, external_account_id text, scopes text[] not null default '{}', status text not null default 'not_connected' check(status in ('not_connected','pending','connected','error','revoked')), secret_reference text, last_synced_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.performance_snapshots (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, product_id uuid references public.products(id) on delete cascade, channel text not null, market text not null, metric_date date not null, impressions bigint, clicks bigint, orders bigint, units_sold bigint, gross_revenue numeric(16,2), refunds numeric(16,2), returns bigint, currency char(3) not null default 'USD', source text not null default 'manual', metrics jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.usage_events (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, actor_user_id uuid not null references auth.users(id), event_type text not null, units numeric(14,4) not null default 1 check(units>=0), provider text, model text, estimated_cost_usd numeric(14,6), request_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, actor_user_id uuid not null references auth.users(id), action text not null, resource_type text not null, resource_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function private.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at:=now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['workspaces','products','channel_listings','channel_connections'] loop execute format('drop trigger if exists set_updated_at on public.%I',t); execute format('create trigger set_updated_at before update on public.%I for each row execute function private.set_updated_at()',t); end loop; end $$;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.products enable row level security;
alter table public.agent_runs enable row level security;
alter table public.channel_listings enable row level security;
alter table public.product_assets enable row level security;
alter table public.channel_connections enable row level security;
alter table public.performance_snapshots enable row level security;
alter table public.usage_events enable row level security;
alter table public.audit_logs enable row level security;
drop policy if exists workspaces_read_member on public.workspaces;
create policy workspaces_read_member on public.workspaces for select to authenticated using(created_by=(select auth.uid()) or private.is_workspace_member(id));
drop policy if exists workspaces_insert_owner on public.workspaces;
create policy workspaces_insert_owner on public.workspaces for insert to authenticated with check(created_by=(select auth.uid()));
drop policy if exists workspaces_update_admin on public.workspaces;
create policy workspaces_update_admin on public.workspaces for update to authenticated using(private.can_manage_workspace(id)) with check(private.can_manage_workspace(id));
drop policy if exists workspace_members_read_member on public.workspace_members;
create policy workspace_members_read_member on public.workspace_members for select to authenticated using(user_id=(select auth.uid()) or private.is_workspace_member(workspace_id));
drop policy if exists workspace_members_admin_write on public.workspace_members;
create policy workspace_members_admin_write on public.workspace_members for all to authenticated using(private.can_manage_workspace(workspace_id)) with check(private.can_manage_workspace(workspace_id));
drop policy if exists products_read_member on public.products;
create policy products_read_member on public.products for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists products_insert_member on public.products;
create policy products_insert_member on public.products for insert to authenticated with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
drop policy if exists products_update_member on public.products;
create policy products_update_member on public.products for update to authenticated using(private.is_workspace_member(workspace_id)) with check(private.is_workspace_member(workspace_id));
drop policy if exists products_delete_member on public.products;
create policy products_delete_member on public.products for delete to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists agent_runs_read_member on public.agent_runs;
create policy agent_runs_read_member on public.agent_runs for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists agent_runs_insert_actor on public.agent_runs;
create policy agent_runs_insert_actor on public.agent_runs for insert to authenticated with check(private.is_workspace_member(workspace_id) and actor_user_id=(select auth.uid()));
drop policy if exists agent_runs_update_actor on public.agent_runs;
create policy agent_runs_update_actor on public.agent_runs for update to authenticated using(private.is_workspace_member(workspace_id) and actor_user_id=(select auth.uid())) with check(private.is_workspace_member(workspace_id) and actor_user_id=(select auth.uid()));
drop policy if exists channel_listings_read_member on public.channel_listings;
create policy channel_listings_read_member on public.channel_listings for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists channel_listings_insert_member on public.channel_listings;
create policy channel_listings_insert_member on public.channel_listings for insert to authenticated with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
drop policy if exists channel_listings_update_member on public.channel_listings;
create policy channel_listings_update_member on public.channel_listings for update to authenticated using(private.is_workspace_member(workspace_id)) with check(private.is_workspace_member(workspace_id));
drop policy if exists product_assets_member_access on public.product_assets;
create policy product_assets_member_access on public.product_assets for all to authenticated using(private.is_workspace_member(workspace_id)) with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
drop policy if exists channel_connections_member_read on public.channel_connections;
create policy channel_connections_member_read on public.channel_connections for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists channel_connections_admin_write on public.channel_connections;
create policy channel_connections_admin_write on public.channel_connections for all to authenticated using(private.can_manage_workspace(workspace_id)) with check(private.can_manage_workspace(workspace_id));
drop policy if exists performance_member_read on public.performance_snapshots;
create policy performance_member_read on public.performance_snapshots for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists usage_events_member_read on public.usage_events;
create policy usage_events_member_read on public.usage_events for select to authenticated using(private.is_workspace_member(workspace_id));
drop policy if exists usage_events_actor_insert on public.usage_events;
create policy usage_events_actor_insert on public.usage_events for insert to authenticated with check(private.is_workspace_member(workspace_id) and actor_user_id=(select auth.uid()));
drop policy if exists audit_logs_admin_read on public.audit_logs;
create policy audit_logs_admin_read on public.audit_logs for select to authenticated using(private.can_manage_workspace(workspace_id));
drop policy if exists audit_logs_actor_insert on public.audit_logs;
create policy audit_logs_actor_insert on public.audit_logs for insert to authenticated with check(private.is_workspace_member(workspace_id) and actor_user_id=(select auth.uid()));
grant usage on schema public to authenticated;
grant select,insert,update on public.workspaces to authenticated;
grant select on public.workspace_members to authenticated;
grant select,insert,update,delete on public.products to authenticated;
grant select,insert,update on public.agent_runs to authenticated;
grant select,insert,update on public.channel_listings to authenticated;
grant select,insert,update,delete on public.product_assets to authenticated;
grant select,insert,update,delete on public.channel_connections to authenticated;
grant select on public.performance_snapshots to authenticated;
grant select,insert on public.usage_events to authenticated;
grant select,insert on public.audit_logs to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('commerce-assets','commerce-assets',false,20971520,array['image/jpeg','image/png','image/webp','video/mp4','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists commerce_assets_member_read on storage.objects;
create policy commerce_assets_member_read on storage.objects for select to authenticated using(bucket_id='commerce-assets' and case when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then private.is_workspace_member(((storage.foldername(name))[1])::uuid) else false end);
drop policy if exists commerce_assets_member_insert on storage.objects;
create policy commerce_assets_member_insert on storage.objects for insert to authenticated with check(bucket_id='commerce-assets' and case when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then private.is_workspace_member(((storage.foldername(name))[1])::uuid) else false end);
drop policy if exists commerce_assets_member_update on storage.objects;
create policy commerce_assets_member_update on storage.objects for update to authenticated using(bucket_id='commerce-assets' and case when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then private.is_workspace_member(((storage.foldername(name))[1])::uuid) else false end) with check(bucket_id='commerce-assets' and case when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then private.is_workspace_member(((storage.foldername(name))[1])::uuid) else false end);
drop policy if exists commerce_assets_member_delete on storage.objects;
create policy commerce_assets_member_delete on storage.objects for delete to authenticated using(bucket_id='commerce-assets' and case when (storage.foldername(name))[1] ~ '^[0-9a-fA-F-]{36}$' then private.is_workspace_member(((storage.foldername(name))[1])::uuid) else false end);
